//! Construct small decoding domains, practical buffers, and shrinkable 1 MiB payloads.

use std::fmt;

use proptest::{prelude::*, strategy::BoxedStrategy};

/// Keep a generated failure value useful in logs without dumping its byte body.
#[derive(Clone, PartialEq, Eq)]
pub(crate) struct Payload(Vec<u8>);

impl Payload {
    /// Store bytes generated by one of the bounded strategies.
    pub(crate) const fn new(bytes: Vec<u8>) -> Self { Self(bytes) }

    /// Borrow the generated bytes for the subprocess boundary check.
    pub(crate) fn as_bytes(&self) -> &[u8] { &self.0 }

    /// Return the generated byte length for replay evidence.
    pub(crate) fn len(&self) -> usize { self.0.len() }
}

impl fmt::Debug for Payload {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("Payload")
            .field("byte_len", &self.len())
            .finish()
    }
}

/// Keep the four small-property buffer regimes independently accountable.
#[derive(Clone, Copy, Debug)]
pub(crate) enum SmallBufferBand {
    /// Exercise one-byte through eight-byte reads.
    Tiny,
    /// Exercise practical sizes below the default buffer.
    Medium,
    /// Exercise the default buffer explicitly.
    Default,
    /// Exercise a read buffer just above the default.
    AboveDefault,
}

/// Return a constructive payload strategy covering valid and malformed UTF-8.
pub(crate) fn small_payload_strategy() -> BoxedStrategy<Payload> {
    prop_oneof![
        4 => prop::collection::vec(any::<u8>(), 0..=4096),
        2 => ascii_payload_strategy(),
        1 => scalar_run(prop::char::range('\u{80}', '\u{7ff}'), 2048),
        1 => scalar_run(
            prop::char::ranges(vec!['\u{800}'..='\u{d7ff}', '\u{e000}'..='\u{ffff}'].into()),
            1365,
        ),
        1 => scalar_run(prop::char::range('\u{10000}', '\u{10ffff}'), 1024),
        2 => mixed_valid_and_invalid_payload_strategy(),
    ]
    .prop_map(Payload::new)
    .boxed()
}

/// Return a buffer strategy confined to one plan-defined small-input band.
pub(crate) fn small_buffer_strategy(band: SmallBufferBand) -> BoxedStrategy<u32> {
    match band {
        SmallBufferBand::Tiny => (1u32..=8).boxed(),
        SmallBufferBand::Medium => (9u32..=65_535).boxed(),
        SmallBufferBand::Default => Just(65_536).boxed(),
        SmallBufferBand::AboveDefault => Just(65_537).boxed(),
    }
}

/// Return a bounded pattern/repetition/tail strategy for lengths around 1 MiB.
pub(crate) fn large_payload_strategy() -> BoxedStrategy<Payload> {
    (1_048_572usize..=1_048_580)
        .prop_flat_map(patterned_large_payload_strategy)
        .prop_map(Payload::new)
        .boxed()
}

/// Build a deterministic named payload with a stable repeated prefix and tail.
pub(crate) fn patterned_large_witness(length: usize, tail: &[u8]) -> Vec<u8> {
    let pattern = b"cuprum-boundary/";
    let prefix_length = length - tail.len();
    let mut payload = pattern
        .iter()
        .cycle()
        .take(prefix_length)
        .copied()
        .collect::<Vec<_>>();
    payload.extend_from_slice(tail);
    payload
}

fn ascii_payload_strategy() -> BoxedStrategy<Vec<u8>> {
    prop::collection::vec(0u8..=0x7f, 0..=4096).boxed()
}

fn scalar_run(
    scalars: impl Strategy<Value = char> + 'static,
    maximum_scalars: usize,
) -> BoxedStrategy<Vec<u8>> {
    prop::collection::vec(scalars, 0..=maximum_scalars)
        .prop_map(|values| values.into_iter().collect::<String>().into_bytes())
        .boxed()
}

fn mixed_valid_and_invalid_payload_strategy() -> BoxedStrategy<Vec<u8>> {
    let valid_run = || {
        prop::collection::vec(any::<char>(), 0..=500)
            .prop_map(|characters| characters.into_iter().collect::<String>().into_bytes())
    };
    (
        valid_run(),
        prop::collection::vec(0x80u8..=0xbf, 1..=8),
        valid_run(),
    )
        .prop_map(|(prefix, malformed, suffix)| {
            let mut payload = Vec::with_capacity(prefix.len() + malformed.len() + suffix.len());
            payload.extend(prefix);
            payload.extend(malformed);
            payload.extend(suffix);
            payload
        })
        .boxed()
}

fn patterned_large_payload_strategy(target_length: usize) -> BoxedStrategy<Vec<u8>> {
    let pattern = prop::collection::vec(any::<u8>(), 1..=128);
    (pattern, 0usize..=3)
        .prop_flat_map(move |(pattern_candidate, repetition_shortfall)| {
            // The pattern strategy excludes empty vectors, so division is defined.
            let maximum_repetitions = target_length
                .checked_div(pattern_candidate.len())
                .unwrap_or_default();
            let repeat_count = maximum_repetitions.saturating_sub(repetition_shortfall);
            let tail_length = target_length - repeat_count * pattern_candidate.len();
            let tail = prop::collection::vec(any::<u8>(), tail_length..=tail_length);
            (Just(pattern_candidate), Just(repeat_count), tail).prop_map(
                |(pattern_bytes, generated_repeats, tail_bytes)| {
                    let mut payload = pattern_bytes.repeat(generated_repeats);
                    payload.extend(tail_bytes);
                    payload
                },
            )
        })
        .boxed()
}
